import 'package:hive_ce/hive.dart';
import 'package:hive_ce_flutter/hive_flutter.dart';
import 'models/models.dart';
import '../core/constants/app_constants.dart';

// NOTE: Adapter classes (e.g. ShopProfileAdapter) are generated as 'part of'
// each model file. They are already accessible via the models.dart barrel import above.
// Do NOT import the .g.dart files directly here.

/// Initializes Hive and opens all boxes. Must be called once from main() before runApp().
Future<void> initHive() async {
  await Hive.initFlutter();

  // Register all TypeAdapters (generated by build_runner, part of each model file)
  Hive.registerAdapter(ShopProfileAdapter());
  Hive.registerAdapter(CustomerAdapter());
  Hive.registerAdapter(MenuItemAdapter());
  Hive.registerAdapter(MenuCategoryAdapter());
  Hive.registerAdapter(MealEntryAdapter());
  Hive.registerAdapter(AdditionalItemEntryAdapter());
  Hive.registerAdapter(PaymentAdapter());
  Hive.registerAdapter(PaymentMethodAdapter());
  Hive.registerAdapter(AdjustmentAdapter());
  Hive.registerAdapter(MonthlyBillAdapter());
  Hive.registerAdapter(BillStatusAdapter());
  Hive.registerAdapter(AuditEntryAdapter());
  Hive.registerAdapter(AuditActionAdapter());

  // Open all boxes
  await Hive.openBox<ShopProfile>(AppConstants.shopProfileBox);
  await Hive.openBox<Customer>(AppConstants.customerBox);
  await Hive.openBox<MenuItem>(AppConstants.menuItemBox);
  await Hive.openBox<MealEntry>(AppConstants.mealEntryBox);
  await Hive.openBox<AdditionalItemEntry>(AppConstants.additionalItemEntryBox);
  await Hive.openBox<Payment>(AppConstants.paymentBox);
  await Hive.openBox<Adjustment>(AppConstants.adjustmentBox);
  await Hive.openBox<MonthlyBill>(AppConstants.monthlyBillBox);
  await Hive.openBox<AuditEntry>(AppConstants.auditEntryBox);
}
